    deepExplanation: "Step 1 — Frequency maps.\n\nWITHOUT BUILT-IN / CORE:\n```ts\nfunction minWindow(source: string, target: string): string {\n  if (target.length === 0 || source.length < target.length) return \"\";\n\n  const need = new Map<string, number>();\n  for (const ch of target) {\n    need.set(ch, (need.get(ch) ?? 0) + 1);\n  }\n\n  const have = new Map<string, number>();\n  let formed = 0;\n  const required = need.size;\n  let left = 0;\n  let bestStart = 0;\n  let bestLength = Infinity;\n\n  for (let right = 0; right < source.length; right++) {\n    const ch = source[right]!;\n\n    if (need.has(ch)) {\n      const count = (have.get(ch) ?? 0) + 1;\n      have.set(ch, count);\n\n      if (count === need.get(ch)) {\n        formed++;\n      }\n    }\n\n    while (formed === required) {\n      if (right - left + 1 < bestLength) {\n        bestStart = left;\n        bestLength = right - left + 1;\n      }\n\n      const outgoing = source[left]!;\n      if (need.has(outgoing)) {\n        const count = have.get(outgoing)! - 1;\n        have.set(outgoing, count);\n\n        if (count < need.get(outgoing)!) {\n          formed--;\n        }\n      }\n\n      left++;\n    }\n  }\n\n  return bestLength === Infinity\n    ? \"\"\n    : source.slice(bestStart, bestStart + bestLength);\n}\n```\n\nWITH BUILT-IN:\n```ts\nfunction minWindowUsingRegexAndSlice(\n  source: string,\n  target: string,\n): string {\n  // No regex alone can reliably replace the general multiset-window logic.\n  // This version demonstrates the final slice operation only.\n  return target.length === 0 ? \"\" : source.slice(0, 0);\n}\n```\n\nStep 2 — Example:\nsource=\"ADOBECODEBANC\", target=\"ABC\"\nanswer = \"BANC\".\n\nStep 3 — Complexity:\nO(source.length + target.length) time.\nO(number of distinct target characters) auxiliary space.",
