    deepExplanation: "Step 1 — Example: determine whether a string contains any permutation of a pattern.\n\nWITHOUT BUILT-IN / CORE:\n```ts\nfunction containsPermutation(text: string, pattern: string): boolean {\n  if (pattern.length === 0) return true;\n  if (pattern.length > text.length) return false;\n\n  const need = new Map<string, number>();\n  const have = new Map<string, number>();\n\n  for (const ch of pattern) {\n    need.set(ch, (need.get(ch) ?? 0) + 1);\n  }\n\n  let matched = 0;\n\n  for (let right = 0; right < text.length; right++) {\n    const incoming = text[right]!;\n\n    if (need.has(incoming)) {\n      const count = (have.get(incoming) ?? 0) + 1;\n      have.set(incoming, count);\n\n      if (count === need.get(incoming)) {\n        matched++;\n      }\n    }\n\n    if (right >= pattern.length) {\n      const outgoing = text[right - pattern.length]!;\n\n      if (need.has(outgoing)) {\n        const count = have.get(outgoing)!;\n        if (count === need.get(outgoing)) {\n          matched--;\n        }\n        have.set(outgoing, count - 1);\n      }\n    }\n\n    if (matched === need.size) return true;\n  }\n\n  return false;\n}\n```\n\nWITH BUILT-IN:\n```ts\nfunction containsPermutationUsingSort(\n  text: string,\n  pattern: string,\n): boolean {\n  if (pattern.length === 0) return true;\n\n  const wanted = [...pattern].sort().join(\"\");\n\n  for (let i = 0; i + pattern.length <= text.length; i++) {\n    const window = [...text.slice(i, i + pattern.length)]\n      .sort()\n      .join(\"\");\n\n    if (window === wanted) return true;\n  }\n\n  return false;\n}\n```\n\nStep 2 — Example:\ntext=\"eidbaooo\", pattern=\"ab\"\nwindow \"ba\" is a permutation → true.\n\nStep 3 — Complexity:\nFrequency window = O(n) average time for map operations.\nSort baseline = O(n·k log k), where k is pattern length.",
